-- =============================================================================
-- Migracion independiente: igualar PRODUCCION (medditech) con DESARROLLO (laboratorio)
-- Fecha: 2026-11-21   Referencia: sql/comparar desarrollo-produccion 21-11-2026/
-- Compatible MySQL 5.7+/8 y MariaDB 10.x/11.x. Idempotente (reejecutable).
-- NO borra ni modifica datos. Solo estructura: indices, claves foraneas y 1 default.
--
-- Contenido:
--  1. caja_movimientos: 3 indices
--  2. cotizaciones: 3 indices + rol_creador sin DEFAULT (como dev)
--  3. convenio_cliente / empresa_cliente: UNIQUE uq_*
--  4. examenes_cliente / _convenio / _empresa / _promocion: indices idx_* (nombres de dev)
--  5. Claves foraneas (14). Cada FK se crea SOLO si no hay registros huerfanos;
--     si los hay se omite con aviso (ver consulta de huerfanos al final).
--  6. Eliminacion de indices simples redundantes que dev ya no tiene
--     (solo si el indice equivalente idx_* existe). No afecta datos.
-- =============================================================================

SET @db := DATABASE();

-- ---------------------------------------------------------------------------
-- 1. caja_movimientos
-- ---------------------------------------------------------------------------
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='caja_movimientos' AND INDEX_NAME='idx_mov_ref_tipo_origen')>0, "SELECT 'idx_mov_ref_tipo_origen ya existe' AS info", "ALTER TABLE `caja_movimientos` ADD INDEX `idx_mov_ref_tipo_origen` (`referencia_id`,`tipo`,`origen`,`referencia_tipo`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='caja_movimientos' AND INDEX_NAME='idx_mov_fecha_hora')>0, "SELECT 'idx_mov_fecha_hora ya existe' AS info", "ALTER TABLE `caja_movimientos` ADD INDEX `idx_mov_fecha_hora` (`fecha_hora`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='caja_movimientos' AND INDEX_NAME='idx_mov_caja_tipo_efectivo')>0, "SELECT 'idx_mov_caja_tipo_efectivo ya existe' AS info", "ALTER TABLE `caja_movimientos` ADD INDEX `idx_mov_caja_tipo_efectivo` (`caja_id`,`tipo`,`afecta_efectivo`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

-- ---------------------------------------------------------------------------
-- 2. cotizaciones
-- ---------------------------------------------------------------------------
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='cotizaciones' AND INDEX_NAME='idx_cotizaciones_comprobante_tipo')>0, "SELECT 'idx_cotizaciones_comprobante_tipo ya existe' AS info", "ALTER TABLE `cotizaciones` ADD INDEX `idx_cotizaciones_comprobante_tipo` (`comprobante_tipo`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='cotizaciones' AND INDEX_NAME='idx_cotizaciones_receptor_numero_documento')>0, "SELECT 'idx_cotizaciones_receptor_numero_documento ya existe' AS info", "ALTER TABLE `cotizaciones` ADD INDEX `idx_cotizaciones_receptor_numero_documento` (`receptor_numero_documento`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='cotizaciones' AND INDEX_NAME='idx_cotizaciones_codprest_fecha')>0, "SELECT 'idx_cotizaciones_codprest_fecha ya existe' AS info", "ALTER TABLE `cotizaciones` ADD INDEX `idx_cotizaciones_codprest_fecha` (`codigo_prestacional`,`fecha`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

-- rol_creador: dev lo tiene NOT NULL sin DEFAULT (lo deja asi 2026_08_30_expandir_enum_rol_creador_cotizaciones.sql).
-- crear_cotizacion.php siempre envia rol_creador, no hay otro INSERT en cotizaciones.
SET @sql := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='cotizaciones' AND COLUMN_NAME='rol_creador' AND COLUMN_DEFAULT IS NOT NULL)>0,
    "ALTER TABLE `cotizaciones` MODIFY COLUMN `rol_creador` ENUM('cliente','recepcionista','laboratorista','admin','empresa','convenio','servicio','engineer') NOT NULL",
    "SELECT 'cotizaciones.rol_creador ya no tiene default' AS info"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

-- ---------------------------------------------------------------------------
-- 3. UNIQUE en tablas pivote (prod ya tiene un UNIQUE equivalente sin nombre uq_*,
--    por lo que no puede fallar por duplicados)
-- ---------------------------------------------------------------------------
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='convenio_cliente' AND INDEX_NAME='uq_convenio_cliente')>0, "SELECT 'uq_convenio_cliente ya existe' AS info", "ALTER TABLE `convenio_cliente` ADD UNIQUE KEY `uq_convenio_cliente` (`convenio_id`,`cliente_id`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='empresa_cliente' AND INDEX_NAME='uq_empresa_cliente')>0, "SELECT 'uq_empresa_cliente ya existe' AS info", "ALTER TABLE `empresa_cliente` ADD UNIQUE KEY `uq_empresa_cliente` (`empresa_id`,`cliente_id`)"); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

