-- Claves foraneas fk_* presentes (deben ser 14; las faltantes indican huerfanos)
SELECT TABLE_NAME, CONSTRAINT_NAME FROM information_schema.TABLE_CONSTRAINTS
WHERE CONSTRAINT_SCHEMA = DATABASE() AND CONSTRAINT_TYPE = 'FOREIGN KEY' AND CONSTRAINT_NAME LIKE 'fk\_%'
ORDER BY TABLE_NAME, CONSTRAINT_NAME;

-- Huerfanos por relacion (todo debe dar 0; si no, depurar y reejecutar este script)
SELECT 'examenes_cliente.cliente_id' AS relacion, COUNT(*) AS huerfanos FROM examenes_cliente c LEFT JOIN clientes p ON p.id=c.cliente_id WHERE c.cliente_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_cliente.examen_id', COUNT(*) FROM examenes_cliente c LEFT JOIN examenes p ON p.id=c.examen_id WHERE c.examen_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_convenio.convenio_id', COUNT(*) FROM examenes_convenio c LEFT JOIN convenios p ON p.id=c.convenio_id WHERE c.convenio_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_convenio.examen_id', COUNT(*) FROM examenes_convenio c LEFT JOIN examenes p ON p.id=c.examen_id WHERE c.examen_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_empresa.empresa_id', COUNT(*) FROM examenes_empresa c LEFT JOIN empresas p ON p.id=c.empresa_id WHERE c.empresa_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_empresa.examen_id', COUNT(*) FROM examenes_empresa c LEFT JOIN examenes p ON p.id=c.examen_id WHERE c.examen_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_promocion.examen_id', COUNT(*) FROM examenes_promocion c LEFT JOIN examenes p ON p.id=c.examen_id WHERE c.examen_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'examenes_promocion.promocion_id', COUNT(*) FROM examenes_promocion c LEFT JOIN promociones p ON p.id=c.promocion_id WHERE c.promocion_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'promociones_empresa.empresa_id', COUNT(*) FROM promociones_empresa c LEFT JOIN empresas p ON p.id=c.empresa_id WHERE c.empresa_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'promociones_empresa.promocion_id', COUNT(*) FROM promociones_empresa c LEFT JOIN promociones p ON p.id=c.promocion_id WHERE c.promocion_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'promociones_examen.examen_id', COUNT(*) FROM promociones_examen c LEFT JOIN examenes p ON p.id=c.examen_id WHERE c.examen_id IS NOT NULL AND p.id IS NULL
UNION ALL SELECT 'promociones_examen.promocion_id', COUNT(*) FROM promociones_examen c LEFT JOIN promociones p ON p.id=c.promocion_id WHERE c.promocion_id IS NOT NULL AND p.id IS NULL
